	local anim = { 'idle', 'idle', 'idle', 'idle', 'cast', 'idle', 'idle', 'idle', 'idle', 'idle' }

	for i = 1, self.npc_count do
		local npc = self.characters.npc(i)

		character_util.set_position(npc, self.markers.before_npc_pos(i))
		character_util.set_direction(npc, self.markers.before_npc_dir(i))
		scene_util.set_emotion(npc, self, emotion[i])
		scene_util.set_anim(npc, self, { name = anim[i], one_shot_sfx = false })
		npc.Interactable.Talk = 'fw_stage_4_oneline_3_' .. i
	end
end

function local_class:clear_setting()
	self:default_setting()

	local emotion = { 'tired', 'smile', 'idle', 'attack' }
	local anim = { 'idle', 'idle', 'idle', 'idle' }

	for i = self.after_npc_index, self.npc_count do
		local npc = self.characters.npc(i)

		character_util.set_position(npc, self.markers.after_npc_pos(i))
		character_util.set_direction(npc, self.markers.after_npc_dir(i))
		scene_util.set_emotion(npc, self, emotion[i + 1 - self.after_npc_index])
		scene_util.set_anim(npc, self, { name = anim[i + 1 - self.after_npc_index], one_shot_sfx = false })
		npc.Interactable.Talk = 'fw_stage_4_oneline_3_after_' .. i
	end
end

return {
	create = function()
		return local_class()
	end
}

