		HasPostSection = false
	}

	self.scene_version = scene_util.default_version + 1

	--npc
	self.character = metatable_helper.inherit({
		spec = {
			fire_harpy = 'sub_rager_fire_harpy',
			fire_rager = 'sub_rager_fire_rager',
		}
	}, function(this, key)
		return get_character(this.spec[key])
	end)

	--gimmick
	self.gimmick = metatable_helper.inherit({
		spec = {
			protein = 'sub_rager_protein',
			broken_protein = 'sub_rager_broken_protein',
			jump = 'sub_rager_jump',
		}
	}, function(this, key)
		return get_field_object(this.spec[key])
	end)

	--fx data
	self.fx_data = {
		fx_pool = {},

		--- @param this self
		--- @param key string
		--- @param fx IFieldObject
		insert = function(this, key, fx)
			if this:get(key) == nil then
				this.fx_pool[key] = fx
			end
		end,

		--- @param this self
		--- @param key string
		get = function(this, key)
			if this.fx_pool[key] == nil then
				return nil
			end

			return this.fx_pool[key]
		end,

		--- @param this self
		--- @param key string
		dispose = function(this, key)
			local fx = this:get(key)

			if fx ~= nil then
				fx:Dispose()
				this.fx_pool[key] = nil
			end
		end,

		--- @param this self
		dispose_all = function(this)
			for key, fx in pairs(this.fx_pool) do
				if fx ~= nil then
					fx:Dispose()
					this.fx_pool[key] = nil
				end
			end
		end,
	}

	--fx
	self.fx = metatable_helper.create_fx_accessor({
		fire_ball = function()
			return unity_object_pool.GetOrCreate('fx_fw_fireball_explosion')
		end,
		explosion = function()
