		end,
		flame_area = function()
			return unity_object_pool.GetOrCreate('fx_flame_area_loop')
		end,
		hit = function()
			return unity_object_pool.GetOrCreate('FX_hit')
		end,
		explosion_boss = function()
			return unity_object_pool.GetOrCreate('FX_explosion_boss')
		end,
		lava_drop = function()
			return unity_object_pool.GetOrCreate('fx_fw_lava_drop')
		end,
	})

	self.door = {
		name = 'sub_rager_door',
		open = function(this)
			message_system:Publish(CS.Oak.DoorOpenEvent.Create(this.name, true))
		end
	}
