--화면쪽으로 날라가는 연출 4인 파티 사양.
function local_class:party_screen_out_fly_away_async(center_pos)
	local duration = 1
	local rotate_offset = {
		-720,
		720,
		-720,
		720,
	}
	local pos_offset = {
		vector(-5, 0, -12),
		vector(5, 0, -12),
		vector(-12, 0, 0),
		vector(12, 0, 0),
	}
	local scale_offset = {
		7, 7, 1, 1,
	}
	local height_offset = {
		10, 10, 3, 3
	}

	music_player_util.play_sfx_one_shot('01_fall_down_01')

	party_util.foreach_member(function(index, member)
		local num = index + 1
		character_util.spine_rotate(member, rotate_offset[num], duration + 0.2)
		character_util.spine_scale(member, unity_class.vector3.one * scale_offset[num], duration)
		character_util.set_active_shadow(member, false)
		member.SpineController:SetSortingLayer('Top Effects', 1000)

		scene_util.set_emotion(member, self, 'damaged')
		scene_util.set_anim(member, self, { name = 'embarrassed', one_shot_sfx = false })
	end)

	coroutine_util.while_each_frame(duration, function(progress)
		party_util.foreach_member(function(index, member)
			local num = index + 1
			local cur_value = unity_class.vector3.Lerp(center_pos, center_pos + pos_offset[num], progress)
			local y = math.sin(math.pi * progress) * height_offset[num]

			member.Position = vector_util.get_x0z(cur_value, y)
		end)
	end)

	party_util.foreach_member(function(index, member)
		member.SpineController:SetSortingLayer('Default', 0)
		character_util.set_active_shadow(member, true)
		character_util.spine_scale(member, unity_class.vector3.one, 0)
		character_util.spine_rotate(member, 0, 0)

		character_util.remove_anim_and_emotion(member)
	end)
end

function local_class:load_resource()
end

function local_class:dispose()
	self.super:dispose()
end

function local_class:on_event(e)
	return false
end

function local_class:on_stage_loaded()
	if self.cs_controller.QuestProgress ~= nil and
			self.cs_controller.QuestProgress.IsComplete then
		self:post_simple_setting()
	else
		self.fx:create_all()
	end
end

function local_class:on_stage_end()
	self.fx_data:dispose()
end

--target_pos 정렬하는 이동 함수
function local_class:align_harpy_async(target_pos, dir, duration)
	local offset = {
		vector(0, 0, 0),
		vector(0, 0, -1),
		vector(0, 0, -2),
		vector(0, 0, 1),
	}

	party_util.foreach_member(function(index, member)
		wp_util.move_with_end_callback(member, target_pos + offset[index + 1],
				nil, duration, self, nil, { last_direction = dir })
	end)

	wp_util.wait_move_end(self)
end

function local_class:post_simple_setting()
	self.gimmick.protein = vector(999, 0, 999)

	local zone = field_util.get_zone('sub_rager_puzzle_area')
	local fo_list = CS.Oak.LuaCollisionUtil.GetFieldObjectsCollidedBy(zone.Bounds, unity_class.vector3.zero)

	for i = 0, fo_list.Count - 1 do
		local fo = fo_list[i]

		if not type_util.is_string(fo.Name) then
			goto continue
		end

		if string_helper.start_with(fo.Name, '[GIMMICK]rock') or
				string_helper.start_with(fo.Name, '[GIMMICK]small_rock') then
			field_object_util.set_active_state(fo, active_state_type.disabled)
		end

		:: continue ::
	end
end

return local_class

